-- Milestone 4a: tenant administration (ADR-0004).
-- Part 1 is generated by Prisma from schema.prisma. Part 2 (security) is hand-written.
-- Runs as kenisha_migrator with search_path = kenisha. One transaction; ASCII only.

BEGIN;

-- ===========================================================================
-- Part 1: tables (generated)
-- ===========================================================================

-- CreateEnum
CREATE TYPE "InvitationStatus" AS ENUM ('PENDING', 'ACCEPTED', 'REVOKED');

-- CreateTable
CREATE TABLE "staff_invitations" (
    "id" UUID NOT NULL DEFAULT uuidv7(),
    "tenant_id" UUID NOT NULL,
    "display_name" VARCHAR(200) NOT NULL,
    "phone_e164" VARCHAR(16) NOT NULL,
    "email" VARCHAR(254),
    "roles" "TenantRole"[],
    "branch_ids" UUID[],
    "token_hash" CHAR(64) NOT NULL,
    "status" "InvitationStatus" NOT NULL DEFAULT 'PENDING',
    "expires_at" TIMESTAMPTZ(3) NOT NULL,
    "invited_by_user_id" UUID,
    "invited_by_platform_user_id" UUID,
    "accepted_user_id" UUID,
    "accepted_at" TIMESTAMPTZ(3),
    "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(3) NOT NULL,

    CONSTRAINT "staff_invitations_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE UNIQUE INDEX "staff_invitations_token_hash_key" ON "staff_invitations"("token_hash");

-- CreateIndex
CREATE INDEX "staff_invitations_tenant_id_status_idx" ON "staff_invitations"("tenant_id", "status");

-- AddForeignKey
ALTER TABLE "staff_invitations" ADD CONSTRAINT "staff_invitations_tenant_id_fkey" FOREIGN KEY ("tenant_id") REFERENCES "tenants"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "staff_invitations" ADD CONSTRAINT "staff_invitations_tenant_id_invited_by_user_id_fkey" FOREIGN KEY ("tenant_id", "invited_by_user_id") REFERENCES "users"("tenant_id", "id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "staff_invitations" ADD CONSTRAINT "staff_invitations_invited_by_platform_user_id_fkey" FOREIGN KEY ("invited_by_platform_user_id") REFERENCES "platform_users"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "staff_invitations" ADD CONSTRAINT "staff_invitations_tenant_id_accepted_user_id_fkey" FOREIGN KEY ("tenant_id", "accepted_user_id") REFERENCES "users"("tenant_id", "id") ON DELETE RESTRICT ON UPDATE CASCADE;


-- ===========================================================================
-- Part 2: security (hand-written - review carefully)
-- ===========================================================================

-- Data checks ------------------------------------------------------------------
ALTER TABLE "staff_invitations"
  ADD CONSTRAINT "staff_invitations_phone_e164" CHECK ("phone_e164" ~ '^\+[1-9][0-9]{6,14}$'),
  ADD CONSTRAINT "staff_invitations_email_lowercase" CHECK ("email" IS NULL OR "email" = lower("email")),
  ADD CONSTRAINT "staff_invitations_token_hash_hex" CHECK ("token_hash" ~ '^[0-9a-f]{64}$'),
  ADD CONSTRAINT "staff_invitations_one_inviter" CHECK (num_nonnulls("invited_by_user_id", "invited_by_platform_user_id") = 1),
  ADD CONSTRAINT "staff_invitations_staff_roles_only" CHECK (
    cardinality("roles") > 0
    AND NOT ("roles" && ARRAY['PATIENT', 'PARENT_GUARDIAN']::"TenantRole"[])
  ),
  ADD CONSTRAINT "staff_invitations_acceptance_complete" CHECK (
    ("status" = 'ACCEPTED') = ("accepted_user_id" IS NOT NULL AND "accepted_at" IS NOT NULL)
  );

-- Lifecycle: PENDING -> PENDING (resend) / ACCEPTED / REVOKED. Accepted and revoked are final.
CREATE FUNCTION "staff_invitations_guard"() RETURNS trigger
  LANGUAGE plpgsql
  SET search_path = pg_catalog, pg_temp
  AS $$
  BEGIN
    IF OLD.status <> 'PENDING' THEN
      RAISE EXCEPTION 'invitation is already % and cannot change', OLD.status
        USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END
  $$;

CREATE TRIGGER "staff_invitations_guard"
  BEFORE UPDATE ON "staff_invitations"
  FOR EACH ROW EXECUTE FUNCTION "staff_invitations_guard"();

-- staff_invitations: hospital role ------------------------------------------------
ALTER TABLE "staff_invitations" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "staff_invitations" FORCE ROW LEVEL SECURITY;

GRANT SELECT, INSERT ON "staff_invitations" TO kenisha_app;
GRANT UPDATE ("status", "token_hash", "expires_at", "accepted_user_id", "accepted_at", "updated_at")
  ON "staff_invitations" TO kenisha_app;
CREATE POLICY "staff_invitations_tenant_isolation" ON "staff_invitations" TO kenisha_app
  USING ("tenant_id" = (SELECT "current_tenant_id"()))
  WITH CHECK ("tenant_id" = (SELECT "current_tenant_id"()));
-- A hospital can never forge a platform-created invitation (it may still accept or
-- resend one, which are UPDATEs and leave the inviter columns untouched).
CREATE POLICY "staff_invitations_tenant_insert_own" ON "staff_invitations" AS RESTRICTIVE FOR INSERT
  TO kenisha_app WITH CHECK ("invited_by_platform_user_id" IS NULL);

-- staff_invitations: the ONE narrow platform grant (ADR-0004 section 1) ---------------
-- Insert only first-admin invitations; read only platform-created rows; nothing else.
GRANT SELECT, INSERT ON "staff_invitations" TO kenisha_platform;
CREATE POLICY "staff_invitations_platform_first_admin" ON "staff_invitations" FOR INSERT
  TO kenisha_platform WITH CHECK (
    "roles" = ARRAY['HOSPITAL_ADMIN']::"TenantRole"[]
    AND "invited_by_platform_user_id" IS NOT NULL
    AND "invited_by_user_id" IS NULL
    -- Prisma list columns are nullable arrays: NULL and '{}' both mean "no branches".
    AND coalesce(cardinality("branch_ids"), 0) = 0
    AND "status" = 'PENDING'
  );
CREATE POLICY "staff_invitations_platform_read_own" ON "staff_invitations" FOR SELECT
  TO kenisha_platform USING ("invited_by_platform_user_id" IS NOT NULL);

-- Pre-login hospital lookup now also returns the status (ONBOARDING hospitals must be able
-- to accept their first invitation). Return type changes require drop + create.
DROP FUNCTION "resolve_tenant"(text);
CREATE FUNCTION "resolve_tenant"(p_code text)
  RETURNS TABLE (tenant_id uuid, is_active boolean, status text)
  LANGUAGE sql STABLE SECURITY DEFINER
  SET search_path = pg_catalog, pg_temp
  AS $$
    SELECT t.id, t.status = 'ACTIVE', t.status::text
    FROM kenisha.tenants t
    WHERE t.slug = lower(p_code)
  $$;
REVOKE ALL ON FUNCTION "resolve_tenant"(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION "resolve_tenant"(text) TO kenisha_app;

-- Usage counts for the Super Admin (numbers only, never names or contact details) -----
-- Runs as the schema owner, which under FORCE RLS needs explicit read policies.
CREATE POLICY "branches_owner_usage" ON "branches" FOR SELECT TO kenisha_migrator USING (true);
CREATE POLICY "users_owner_usage" ON "users" FOR SELECT TO kenisha_migrator USING (true);
CREATE POLICY "staff_invitations_owner_usage" ON "staff_invitations" FOR SELECT TO kenisha_migrator USING (true);

CREATE FUNCTION "tenant_usage"()
  RETURNS TABLE (tenant_id uuid, active_branches integer, active_staff integer, pending_invitations integer)
  LANGUAGE sql STABLE SECURITY DEFINER
  SET search_path = pg_catalog, pg_temp
  AS $$
    SELECT t.id,
           (SELECT count(*)::integer FROM kenisha.branches b
             WHERE b.tenant_id = t.id AND b.is_active),
           (SELECT count(*)::integer FROM kenisha.users u
             WHERE u.tenant_id = t.id AND u.account_kind = 'STAFF' AND u.status = 'ACTIVE'),
           (SELECT count(*)::integer FROM kenisha.staff_invitations i
             WHERE i.tenant_id = t.id AND i.status = 'PENDING' AND i.expires_at > now())
    FROM kenisha.tenants t
  $$;
REVOKE ALL ON FUNCTION "tenant_usage"() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION "tenant_usage"() TO kenisha_platform;

-- One-way activation: ONBOARDING -> ACTIVE for the current tenant only, used when the first
-- Hospital Admin accepts. The hospital role still cannot change its own status otherwise.
CREATE POLICY "tenants_owner_activate" ON "tenants" FOR UPDATE TO kenisha_migrator
  USING (true) WITH CHECK (true);

CREATE FUNCTION "activate_onboarding_tenant"()
  RETURNS boolean
  LANGUAGE sql VOLATILE SECURITY DEFINER
  SET search_path = pg_catalog, pg_temp
  AS $$
    WITH activated AS (
      UPDATE kenisha.tenants
      SET status = 'ACTIVE', updated_at = now()
      WHERE id = kenisha.current_tenant_id() AND status = 'ONBOARDING'
      RETURNING id
    )
    SELECT EXISTS (SELECT 1 FROM activated)
  $$;
REVOKE ALL ON FUNCTION "activate_onboarding_tenant"() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION "activate_onboarding_tenant"() TO kenisha_app;

COMMIT;
